<?php require_once '../config/auth.php';$page_title='Deals Pipeline';$base='../';$stages=['prospecting','qualified','proposal','negotiation','won','lost'];include '../partials/header.php';?><div class="d-flex justify-content-between mb-3"><div><h4>Deals Pipeline</h4><p class="text-muted">Visualize the sales process.</p></div><a class="btn btn-primary" href="form.php">+ Create deal</a></div><div class="pipeline"><?php foreach($stages as $stage):$s=$pdo->prepare("SELECT d.*,c.name customer FROM deals d JOIN customers c ON c.id=d.customer_id WHERE d.stage=? ORDER BY d.created_at DESC");$s->execute([$stage]);$rows=$s->fetchAll();?><div class="stage flex-fill"><div class="d-flex justify-content-between"><b><?=ucfirst($stage)?></b><span class="badge text-bg-light"><?=count($rows)?></span></div><?php foreach($rows as $r):?><div class="deal"><b><?=e($r['title'])?></b><div class="small text-muted"><?=e($r['customer'])?></div><div class="mt-2 fw-bold">$<?=number_format($r['amount'],2)?></div><a class="small" href="form.php?id=<?=$r['id']?>">Edit</a></div><?php endforeach;?></div><?php endforeach;?></div><?php include '../partials/footer.php';?>